19	// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
20	// Eq10.21
21	std::complex<double> FFPMscT(int j1, int j2, int j3, int j4, int j5, int j6,
22	                              FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
23	  std::complex<double> FFPMscT_value;
24	  double Delta3, delta12, delta56;
25	
26	  // Statement functions
27	  auto zab2 = [&za, &zb](int j1, int j2, int j3, int j4) {
28	    return za(j1, j2) * zb(j2, j4) + za(j1, j3) * zb(j3, j4);
29	  };
30	  auto zab = [&za, &zb](int j1, int j2, int j3) {
31	    return za(j1, j2) * zb(j2, j3);
32	  };
33	  auto zba = [&za, &zb](int j1, int j2, int j3) {
34	    return zb(j1, j2) * za(j2, j3);
35	  };
36	  auto zb22b = [&zb, &zab2](int j1, int j2, int j3, int j4, int j5, int j6) {
37	    return
38	      zb(j1, j2) * zab2(j2, j4, j5, j6) + zb(j1, j3) * zab2(j3, j4, j5, j6);
39	  };
40	  // End statement functions
41	
42	  Delta3 = std::pow(s(j1, j2), 2) + std::pow(s(j3, j4), 2) + std::pow(s(j5, j6), 2)
43	    - 2 * s(j1, j2) * s(j3, j4) - 2 * s(j3, j4) * s(j5, j6) - 2 * s(j5, j6) * s(j1, j2);
44	  delta12 = s(j1, j2) - s(j3, j4) - s(j5, j6);
45	  delta56 = s(j5, j6) - s(j1, j2) - s(j3, j4);
46	
47	  FFPMscT_value =
48	    3 * s(j1, j2) * zb(j4, j6) * za(j5, j6) * zab2(j4, j1, j2, j3)
49	      / (zab2(j3, j1, j2, j4) * zab2(j1, j2, j3, j4) * std::pow(Delta3, 2))
50	    * (za(j1, j2) * zb(j5, j6)
51	      * (zab(j5, j6, j1) * delta56 - zab(j5, j2, j1) * delta12)
52	      + t(j1, j2, j4) * (zab(j2, j5, j6) * delta56 - zab(j2, j1, j6) * delta12))
53	
54	    + za(j1, j2) * zb(j4, j6)
55	      / (zab2(j3, j1, j2, j4) * zab2(j1, j2, j3, j4) * Delta3)
56	    * (-zb(j1, j2) * za(j5, j6)
57	      * (3 * zab2(j4, j1, j2, j3) * zab2(j2, j1, j3, j6)
58	        - za(j2, j4) * zb(j3, j6) * (t(j1, j2, j3) - t(j1, j2, j4)))
59	
60	      + zab2(j4, j1, j2, j3)
61	        * (zab(j5, j2, j1) * delta12 - zab(j5, j6, j1) * delta56
62	          + t(j1, j2, j3) * zab2(j5, j2, j4, j1) - t(j1, j2, j4) * zab2(j5, j2, j3, j1))
63	
64	      + za(j4, j5) * t(j1, j2, j3) * (zb22b(j1, j3, j4, j1, j2, j3)
65	        - zba(j1, j2, j4) * zb(j4, j3))
66	      - zab2(j4, j1, j2, j3) * za(j3, j5) * t(j1, j2, j3)
67	        * (zb22b(j1, j3, j4, j1, j2, j4) - zba(j1, j2, j3) * zb(j3, j4))
68	        / zab2(j3, j1, j2, j4))
69	
70	    - zab(j2, j1, j3) * zab(j5, j4, j6)
71	      / (zab2(j3, j1, j2, j4) * zab2(j1, j2, j3, j4))
72	
73	    + 3 * zab(j1, j5, j6) * zab2(j4, j1, j2, j3) / (zab2(j1, j2, j3, j4) * std::pow(Delta3, 2))
74	    * (zab(j2, j1, j3) * (zab(j5, j2, j1) * delta12 - zab(j5, j6, j1) * delta56)
75	      + zab(j1, j2, j3) * (zab(j5, j6, j2) * delta56 - zab(j5, j1, j2) * delta12)
76	        * zab2(j2, j3, j4, j1) / zab2(j1, j3, j4, j2))
77	
78	    + za(j1, j5) / (zab2(j1, j2, j3, j4) * Delta3)
79	    * (-zb(j1, j3)
80	      * (zab(j2, j1, j3) * zab(j4, j5, j6) + zab(j4, j2, j3) * zab(j2, j5, j6)
81	        - zab2(j4, j1, j2, j3) * (zab(j2, j1, j6) - zab(j2, j5, j6)))
82	
83	      + zb(j2, j3) * zab2(j2, j3, j4, j1) / zab2(j1, j3, j4, j2)
84	        * (3 * zab(j1, j5, j6) * zab(j4, j2, j3) - zab(j1, j2, j6) * zab2(j4, j1, j2, j3)
85	          + zb(j2, j3) * za(j1, j4) * zab(j1, j5, j6) * (t(j2, j3, j4) - t(j1, j3, j4))
86	            / zab2(j1, j3, j4, j2)));
87	
88	  FFPMscT_value = FFPMscT_value; // @coverage-probe
89	  return FFPMscT_value;
90	}
