92	extern "C" {
93	  std::complex<double> FFPMscT_wrapper(int j1, int j2, int j3, int j4, int j5, int j6,
94	                                        std::complex<double>* fza, std::complex<double>* fzb) {
95	    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
96	    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
97	    return FFPMscT(j1, j2, j3, j4, j5, j6, za, zb);
98	  }
99	}

