 5	#include <FFPMccT.hpp>
 6	#include <W1jet.hpp>
 7	#include <cmath>
 8	#include <complex>
 9	#include <FArray.hpp>
10	#include <mxpart_mod.hpp>
11	#include <sprods_com_mod.hpp>
12	#include <types.hpp>
