14	// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
15	// Eq.10.17
16	std::complex<double> FFPMccT(int j1, int j2, int j3, int j4, int j5, int j6,
17	                              FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
18	  using namespace types;
19	  using namespace mxpart_mod;
20	  using namespace sprods_com_mod;
21	
22	  std::complex<double> FFPMccT_value;
23	  double delta12, delta34;
24	
25	  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
26	    return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
27	  };
28	  auto zab = [&za, &zb](int i1, int i2, int i3) {
29	    return za(i1,i2)*zb(i2,i3);
30	  };
31	  auto zba = [&za, &zb](int i1, int i2, int i3) {
32	    return zb(i1,i2)*za(i2,i3);
33	  };
34	
35	  delta12 = s(j1,j2) - s(j3,j4) - s(j5,j6);
36	  delta34 = s(j3,j4) - s(j5,j6) - s(j1,j2);
37	
38	  FFPMccT_value =
39	    -std::pow(za(j2,j4),2)*zb(j1,j6)*zab2(j5,j2,j4,j3)
40	    /(za(j2,j3)*std::pow(t(j2,j3,j4),2))
41	    +0.5*zb(j1,j3)*za(j2,j4)*za(j2,j5)*zab2(j5,j2,j4,j3)
42	    /(za(j2,j3)*zb(j3,j4)*za(j5,j6)*t(j2,j3,j4))
43	    +0.5*std::pow(za(j2,j4),2)*zb(j1,j6)*zab2(j4,j1,j3,j6)
44	    /(za(j2,j3)*za(j3,j4)*zb(j5,j6)*t(j2,j3,j4))
45	    -za(j4,j5)*zab(j2,j1,j3)*zab2(j2,j1,j3,j6)
46	    /(za(j2,j3)*t(j1,j2,j3)*zab2(j1,j2,j3,j4))
47	    +0.5/(zab2(j1,j2,j3,j4)*zab2(j1,j3,j4,j2))
48	    *(4*zab(j5,j1,j6)*zab(j4,j2,j3)*zab2(j1,j2,j4,j3)/t(j2,j3,j4)
49	    +zab2(j1,j2,j4,j3)*std::pow(zab2(j5,j2,j4,j3),2)
50	    *(2*s(j3,j4)*s(j5,j6)+delta12*t(j2,j3,j4))
51	    /(zb(j3,j4)*za(j5,j6)*std::pow(t(j2,j3,j4),2))
52	    +std::pow(zab(j5,j1,j3),2)
53	    *(za(j1,j2)*delta12+zab2(j1,j2,j3,j4)*za(j4,j2))
54	    /(za(j2,j3)*zb(j3,j4)*za(j5,j6))
55	    +std::pow(za(j2,j4),3)*std::pow(zb(j2,j6),2)*zab2(j1,j2,j3,j4)
56	    /(za(j2,j3)*za(j3,j4)*zb(j5,j6))
57	    -za(j2,j4)*za(j4,j5)
58	    *zab2(j1,j2,j3,j4)*(zab(j4,j1,j6)-zab(j4,j2,j6))
59	    /(za(j2,j3)*za(j3,j4))
60	    +za(j1,j2)*zb(j3,j6)*(zab(j5,j1,j3)-zab(j5,j2,j3))
61	    *(s(j2,j3)+t(j1,j3,j4))/(za(j2,j3)*zb(j3,j4))
62	    -za(j1,j2)*za(j4,j5)/za(j2,j3)
63	    *(zb(j3,j6)*(2*s(j2,j4)+delta34)-2*zba(j3,j1,j5)*zb(j5,j6)))
64	    +0.5/(zab2(j1,j2,j3,j4)*zab2(j1,j3,j4,j2)*zab2(j3,j1,j2,j4))
65	    *(zab(j1,j4,j6)
66	    *(zab(j5,j1,j3)*s(j1,j3)-zab(j5,j2,j3)*s(j2,j3))
67	    +5*zab(j1,j2,j4)*zab(j4,j1,j3)*zab(j5,j4,j6)
68	    +zab(j5,j4,j3)*zab2(j1,j2,j3,j6)*(s(j1,j3)-s(j2,j4))
69	    +zab(j1,j2,j3)
70	    *(zab(j5,j2,j6)*s(j3,j4)
71	    +zab(j5,j4,j6)*s(j1,j3)
72	    +2*zab(j2,j1,j4)*za(j4,j3)*zab2(j5,j1,j3,j6)/za(j2,j3)
73	    +3*(za(j5,j4)*zb(j4,j3)*za(j3,j1)*zb(j1,j6)
74	    -zab(j5,j3,j6)*s(j2,j4))
75	    -2*(zab(j5,j1,j6)*(s(j1,j4)+s(j2,j4))
76	    +za(j5,j1)*zb(j1,j4)*za(j4,j3)*zb(j3,j6))));
77	
78	  FFPMccT_value = FFPMccT_value; // @coverage-probe
79	  return FFPMccT_value;
80	}
