82	extern "C" {
83	  std::complex<double> FFPMccT_wrapper(int j1, int j2, int j3, int j4, int j5, int j6,
84	                                        std::complex<double>* za_ptr, std::complex<double>* zb_ptr) {
85	    using namespace mxpart_mod;
86	
87	    FArray2D<std::complex<double>> za(za_ptr, mxpart, mxpart);
88	    FArray2D<std::complex<double>> zb(zb_ptr, mxpart, mxpart);
89	
90	    return FFPMccT(j1, j2, j3, j4, j5, j6, za, zb);
91	  }
92	}
